script:
(function () {
  'use strict';
  // Net to gross: finds the gross pay per paycheck that leaves a target net (take-home) amount
  // after 2026 federal income tax, Social Security, Medicare, a flat state rate and deductions.
  // Net pay for a trial annual gross G (same model as the take-home paycheck calculator):
  //   401(k) = G x rate; pre-tax = per-check amount x periods (Section 125: not FICA-taxable)
  //   federal tax on (G - 401(k) - pre-tax - standard deduction), less child/dependent credits
  //   FICA on (G - pre-tax); state = rate x (G - 401(k) - pre-tax); net = G - all of the above
  // G is solved by bisection (net rises with gross), then rounded up to the next cent per check.
  // Verified (Node, scratch tests): single, biweekly, no deductions, 0% state: a $75,000 salary
  // nets $61,592.50 by hand (tax 1,240 + 4,560 + 22% x 8,500 = $7,670; SS $4,650; Medicare $1,087.50),
  // and a $2,368.94 net target solves back to $2,884.62 gross per check ($75,000 / 26).
  // 300 random inputs round-trip: net at the solved gross meets the target to the cent.
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Copied from take-home-paycheck-calculator (verified there). Brackets and standard
  // deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21). Child tax credit $2,200 and
  // $500 other-dependent credit: IRC 24(h) as amended by P.L. 119-21. Social Security wage base
  // and rates: SSA 2026 fact sheet. Medicare and 0.9% Additional Medicare: IRC 3101(b).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var CHILD_CREDIT = 2200;               // per child under 17
  var OTHER_DEPENDENT_CREDIT = 500;
  var CREDIT_PHASEOUT_START = { single: 200000, hoh: 200000, mfs: 200000, mfj: 400000 }; // $50 per $1,000
  var SS_RATE = 0.062, SS_WAGE_BASE = 184500;
  var MEDICARE_RATE = 0.0145, ADDL_MEDICARE_RATE = 0.009, ADDL_MEDICARE_WITHHOLD_START = 200000;
  // ---------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2, minimumFractionDigits: 2 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 1 });

  function num(id) {
    var el = document.getElementById(id);
    if (!el) return NaN;
    var v = parseFloat(el.value);
    return isNaN(v) ? NaN : v;
  }

  function bracketTax(taxable, limits) {
    var tax = 0, lower = 0, marginal = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (taxable > lower) {
        tax += (Math.min(taxable, upper) - lower) * RATES[i];
        marginal = RATES[i];
      }
      lower = upper;
    }
    return { tax: tax, marginal: marginal };
  }

  // Annual federal income tax: AGI - standard deduction - extra deductions, brackets, then
  // non-refundable child / dependent credits (refundable part of the child credit not modelled).
  function federalTax(agi, status, kids, otherDeps, extraDeduction) {
    var taxable = Math.max(0, agi - STANDARD_DEDUCTION[status] - (extraDeduction || 0));
    var bt = bracketTax(taxable, BRACKETS[status]);
    var credits = kids * CHILD_CREDIT + otherDeps * OTHER_DEPENDENT_CREDIT;
    var over = Math.max(0, agi - CREDIT_PHASEOUT_START[status]);
    credits = Math.max(0, credits - Math.ceil(over / 1000) * 50);
    return { taxable: taxable, tax: Math.max(0, bt.tax - credits), marginal: bt.marginal };
  }

  function ficaTax(wages) {
    var ss = SS_RATE * Math.min(wages, SS_WAGE_BASE);
    var medicare = MEDICARE_RATE * wages + ADDL_MEDICARE_RATE * Math.max(0, wages - ADDL_MEDICARE_WITHHOLD_START);
    return { ss: ss, medicare: medicare };
  }

  function paycheck(gross, o) {
    var k401 = gross * o.k401Pct / 100;
    var pretax = Math.min(o.pretaxPer * o.periods, Math.max(0, gross - k401));
    var fedWages = Math.max(0, gross - k401 - pretax);
    var fed = federalTax(fedWages, o.status, o.kids, o.otherDeps, 0);
    var f = ficaTax(Math.max(0, gross - pretax));
    var state = o.stateRate / 100 * fedWages;
    var post = o.postPer * o.periods;
    var net = gross - k401 - pretax - fed.tax - f.ss - f.medicare - state - post;
    return { gross: gross, k401: k401, pretax: pretax, federal: fed.tax, marginal: fed.marginal,
             ss: f.ss, medicare: f.medicare, state: state, post: post, net: net,
             taxes: fed.tax + f.ss + f.medicare + state };
  }

  // Smallest annual gross whose net reaches targetAnnual, or null if it cannot be reached.
  function solveGross(targetAnnual, o) {
    var lo = 0, hi = Math.max(1000, targetAnnual * 2);
    var guard = 0;
    while (paycheck(hi, o).net < targetAnnual) {
      hi *= 2;
      if (++guard > 60 || hi > 1e12) return null;
    }
    for (var i = 0; i < 200 && hi - lo > 1e-6; i++) {
      var mid = (lo + hi) / 2;
      if (paycheck(mid, o).net >= targetAnnual) hi = mid; else lo = mid;
    }
    return hi;
  }

  function setText(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function update() {
    var o = {
      netPer: num('ngNet'), periods: parseInt(document.getElementById('ngFreq').value, 10),
      status: document.getElementById('ngStatus').value, k401Pct: num('ng401k'),
      pretaxPer: num('ngPretax'), kids: Math.round(num('ngKids')), otherDeps: Math.round(num('ngOtherDeps')),
      stateRate: num('ngState'), postPer: num('ngPosttax')
    };
    if (!BRACKETS[o.status]) o.status = 'single';
    if (!(o.periods > 0)) o.periods = 26;
    var error = document.getElementById('ngError');
    var nums = [o.netPer, o.k401Pct, o.pretaxPer, o.kids, o.otherDeps, o.stateRate, o.postPer];
    var bad = nums.some(function (v) { return !isFinite(v) || v < 0; }) || o.netPer <= 0 ||
              o.netPer > 1e7 || o.k401Pct >= 100 || o.stateRate > 20 || o.kids > 20 || o.otherDeps > 20 ||
              o.pretaxPer > 1e7 || o.postPer > 1e7;
    var msg = 'Enter a net paycheck above zero, non-negative deductions, a 401(k) rate below 100% and a state rate from 0 to 20%.';
    var periodsN = o.periods, gross = null;
    if (!bad) {
      gross = solveGross(o.netPer * periodsN, o);
      if (gross === null) { bad = true; msg = 'No gross pay can produce that net paycheck with these deductions. Lower the 401(k) rate.'; }
    }
    error.hidden = !bad;
    if (bad) { error.textContent = msg; return; }

    var grossPer = Math.ceil(gross / periodsN * 100 - 1e-7) / 100;
    var r = paycheck(grossPer * periodsN, o), p = periodsN;
    setText('ngGross', money.format(grossPer));
    setText('ngGrossAnnual', money.format(r.gross));
    setText('ngTaxPer', money.format(r.taxes / p));
    setText('ngCheckNet', money.format(r.net / p));
    setText('ngHourly', money.format(r.gross / 2080));
    setText('ngEffective', r.gross > 0 ? pct.format(r.taxes / r.gross) : '0%');
    setText('ngMarginal', pct.format(r.marginal));

    var rows = [
      ['Gross pay', r.gross],
      ['401(k) / 403(b) contribution', -r.k401],
      ['Other pre-tax deductions', -r.pretax],
      ['Federal income tax', -r.federal],
      ['Social Security (6.2%)', -r.ss],
      ['Medicare', -r.medicare],
      ['State and local income tax', -r.state],
      ['After-tax deductions', -r.post],
      ['Net pay', r.net]
    ];
    document.getElementById('ngBreakdown').innerHTML = rows.map(function (row, i) {
      var cell = function (v) { if (Math.abs(v) < 0.005) return money.format(0); return v < 0 ? '−' + money.format(-v) : money.format(v); };
      var last = i === rows.length - 1;
      return '<tr><th scope="row">' + (last ? '<strong>' + row[0] + '</strong>' : row[0]) + '</th><td>' +
             cell(row[1] / p) + '</td><td>' + cell(row[1]) + '</td></tr>';
    }).join('');

    var noteEl = document.getElementById('ngNote');
    var notes = [];
    if (o.kids + o.otherDeps > 0 && r.federal === 0) notes.push('Your credits cover all of your federal income tax, so federal tax is zero. Part of the child tax credit may still be refundable when you file.');
    noteEl.hidden = notes.length === 0;
    noteEl.textContent = notes.join(' ');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ngForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
